# 공백을 제외한 글자의 개수를 세어보세요.

solution:
text = input()
counts = {}
for ch in text:
    if ch != " ":
        counts[ch] = counts.get(ch, 0) + 1
best = ""
for ch in sorted(counts):
    if best == "" or counts[ch] > counts[best]:
        best = ch
print(best, counts[best])
